import { H3, getSession, useSession, unsealSession } from "../src/index.ts";
import { seal, defaults as sealDefaults } from "../src/utils/internal/iron-crypto.ts";

const OLD = "antiga-0123456789-0123456789-abcdefgh";
const NEW = "nova-0123456789-0123456789-ijklmnop";
const OUTRA = "terceira-0123456789-0123456789-qrstu";

const base = { name: "h3-ref", generateId: () => "fixed-id" };

const sealedWith = (password: string) =>
  seal({ id: "old-id", createdAt: 1_900_000_000_000, data: { foo: "bar" } }, password, sealDefaults);

function describeResponse(res: Response) {
  return {
    status: res.status,
    cookies: res.headers.getSetCookie().map((c) => c.replace(/=[^;]*/, "=<v>")),
  };
}

it("capture", async () => {
  const out: Record<string, any> = {};
  const oldCookie = await sealedWith(OLD);
  const newCookie = await sealedWith(NEW);
  const outraCookie = await sealedWith(OUTRA);

  const variants: Record<string, any> = {
    absent: {},
    undefined: { extraUnsealPasswords: undefined },
    empty: { extraUnsealPasswords: [] },
  };

  for (const [vname, extra] of Object.entries(variants)) {
    const cfg = { ...base, password: NEW, ...extra };
    const app = new H3({});
    app.get("/get", async (event) => {
      const s = await getSession(event, cfg);
      return { id: s.id, data: s.data };
    });
    app.get("/use", async (event) => {
      const s = await useSession(event, cfg);
      return { id: s.id, data: s.data };
    });
    const cases: Record<string, string> = {
      newCookie: newCookie,
      oldCookie: oldCookie,
      outraCookie: outraCookie,
    };
    for (const [cname, value] of Object.entries(cases)) {
      for (const route of ["/get", "/use"]) {
        const res = await app.fetch(
          new Request("http://localhost" + route, { headers: { Cookie: `h3-ref=${value}` } }),
        );
        out[`${vname}|${cname}|${route}`] = {
          ...describeResponse(res),
          body: await res.json(),
        };
      }
    }
  }

  // Direct unsealSession with wrong password
  const direct = async (sealed: string, extra: any) => {
    try {
      await unsealSession({} as any, { ...base, password: NEW, ...extra }, sealed);
      return "no-error";
    } catch (e: any) {
      return { ctor: e?.constructor?.name, message: e?.message };
    }
  };
  out["direct|absent|old"] = await direct(oldCookie, {});
  out["direct|undefined|old"] = await direct(oldCookie, { extraUnsealPasswords: undefined });
  out["direct|empty|old"] = await direct(oldCookie, { extraUnsealPasswords: [] });
  out["direct|absent|outra"] = await direct(outraCookie, {});

  writeFileSync(
    "C:/dev/runs/rcf1f79dec6/node_modules/.cache/ref.json",
    JSON.stringify(out, null, 2),
  );
});

