import type { SessionConfig } from "../src/utils/session.ts";
import { beforeEach, describe, vi } from "vitest";
import {
  useSession,
  getSession,
  updateSession,
  clearSession,
  readBody,
  sealSession,
  unsealSession,
  H3,
  HTTPError,
} from "../src/index.ts";
import { seal, unseal, defaults as sealDefaults } from "../src/utils/internal/iron-crypto.ts";
import { kLegacySeal } from "../src/utils/internal/session.ts";
import { describeMatrix } from "./_setup.ts";
import type { H3Event } from "../src/event.ts";

// All 32+ characters, so none of them hits the minimum length check
const OLD_PASSWORD = "antiga-0123456789-0123456789-abcdefgh";
const NEW_PASSWORD = "nova-0123456789-0123456789-ijklmnop";
const OTHER_PASSWORD = "terceira-0123456789-0123456789-qrstu";
// Same registered symbol as `kUnsealedWithExtra` in src/utils/internal/session.ts
const kUnsealedWithExtra = Symbol.for("h3.internal.session.extra-unseal");

const SESSION_PAYLOAD = { id: "old-id", createdAt: 1_900_000_000_000, data: { foo: "bar" } };
const LEGACY_SEAL_OPTIONS = {
  ...sealDefaults,
  encryption: { ...sealDefaults.encryption, iterations: 1 },
  integrity: { ...sealDefaults.integrity, iterations: 1 },
};
const sealWith = (password: string, payload: object = SESSION_PAYLOAD) =>
  seal(payload, password, sealDefaults);
const cookieValueOf = (setCookie: string) =>
  decodeURIComponent(setCookie.match(/h3-extra=([^;]+)/)![1]);
const cookieShape = (res: Response) =>
  res.headers.getSetCookie().map((cookie) => cookie.replace(/=[^;]*/, "=<v>"));

// Captured before `extraUnsealPasswords` existed, with the cookie named "h3-ref", `password`
// NEW_PASSWORD and cookies sealed with NEW_PASSWORD (newCookie), OLD_PASSWORD (oldCookie) and
// OTHER_PASSWORD (outraCookie). Keys are `variant|cookie|route` (`direct|...` for `unsealSession`).
const REFERENCE: Record<string, unknown> = {
  "absent|newCookie|get": {
    status: 200,
    cookies: [],
    body: { id: "old-id", data: { foo: "bar" } },
  },
  "absent|newCookie|use": {
    status: 200,
    cookies: [],
    body: { id: "old-id", data: { foo: "bar" } },
  },
  "absent|oldCookie|get": { status: 200, cookies: [], body: { id: "fixed-id", data: {} } },
  "absent|oldCookie|use": {
    status: 200,
    cookies: ["h3-ref=<v>; Path=/; HttpOnly; Secure; SameSite=Lax"],
    body: { id: "fixed-id", data: {} },
  },
  "absent|outraCookie|get": { status: 200, cookies: [], body: { id: "fixed-id", data: {} } },
  "absent|outraCookie|use": {
    status: 200,
    cookies: ["h3-ref=<v>; Path=/; HttpOnly; Secure; SameSite=Lax"],
    body: { id: "fixed-id", data: {} },
  },
  "undefined|newCookie|get": {
    status: 200,
    cookies: [],
    body: { id: "old-id", data: { foo: "bar" } },
  },
  "undefined|newCookie|use": {
    status: 200,
    cookies: [],
    body: { id: "old-id", data: { foo: "bar" } },
  },
  "undefined|oldCookie|get": { status: 200, cookies: [], body: { id: "fixed-id", data: {} } },
  "undefined|oldCookie|use": {
    status: 200,
    cookies: ["h3-ref=<v>; Path=/; HttpOnly; Secure; SameSite=Lax"],
    body: { id: "fixed-id", data: {} },
  },
  "undefined|outraCookie|get": { status: 200, cookies: [], body: { id: "fixed-id", data: {} } },
  "undefined|outraCookie|use": {
    status: 200,
    cookies: ["h3-ref=<v>; Path=/; HttpOnly; Secure; SameSite=Lax"],
    body: { id: "fixed-id", data: {} },
  },
  "empty|newCookie|get": {
    status: 200,
    cookies: [],
    body: { id: "old-id", data: { foo: "bar" } },
  },
  "empty|newCookie|use": {
    status: 200,
    cookies: [],
    body: { id: "old-id", data: { foo: "bar" } },
  },
  "empty|oldCookie|get": { status: 200, cookies: [], body: { id: "fixed-id", data: {} } },
  "empty|oldCookie|use": {
    status: 200,
    cookies: ["h3-ref=<v>; Path=/; HttpOnly; Secure; SameSite=Lax"],
    body: { id: "fixed-id", data: {} },
  },
  "empty|outraCookie|get": { status: 200, cookies: [], body: { id: "fixed-id", data: {} } },
  "empty|outraCookie|use": {
    status: 200,
    cookies: ["h3-ref=<v>; Path=/; HttpOnly; Secure; SameSite=Lax"],
    body: { id: "fixed-id", data: {} },
  },
  "direct|absent|old": { ctor: "Error", message: "Bad hmac value" },
  "direct|undefined|old": { ctor: "Error", message: "Bad hmac value" },
  "direct|empty|old": { ctor: "Error", message: "Bad hmac value" },
  "direct|absent|outra": { ctor: "Error", message: "Bad hmac value" },
};

describeMatrix("session", (t, { it, expect }) => {
  const extraConfig = (overrides: Partial<SessionConfig> = {}): SessionConfig => ({
    name: "h3-extra",
    password: NEW_PASSWORD,
    generateId: () => "fixed-id",
    ...overrides,
  });
  const sessionRoute = (path: string, mode: "get" | "use", config: SessionConfig) => {
    t.app.get(path, async (event) => {
      const session =
        mode === "get" ? await getSession(event, config) : await useSession(event, config);
      return { id: session.id, data: session.data };
    });
  };
  // Counts the PBKDF2 derivations (`subtle.deriveBits`) made while `run` executes
  const countDerivations = async <T>(run: () => Promise<T>) => {
    const deriveBits = vi.spyOn(globalThis.crypto.subtle, "deriveBits");
    try {
      const result = await run();
      return { derivations: deriveBits.mock.calls.length, result };
    } finally {
      deriveBits.mockRestore();
    }
  };

  let app: H3;

  let cookie = "";

  let sessionIdCtr = 0;
  const sessionConfig: SessionConfig = {
    name: "h3-test",
    password: "1234567123456712345671234567123456712345671234567",
    generateId: () => ++sessionIdCtr + "",
  };

  beforeEach(() => {
    app = new H3({});
    t.app.all("/", async (event) => {
      const session = await useSession(event, sessionConfig);
      if (event.req.method === "POST") {
        await session.update((await readBody(event)) as any);
      }
      return { session };
    });
    t.app.use(app.handler);
  });

  it("initiates session", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()).toHaveLength(1);
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("sets SameSite=Lax by default", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()[0]).toContain("SameSite=Lax");
  });

  it("allows overriding SameSite via config.cookie", async () => {
    t.app.get("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: "strict" },
      });
      return { session };
    });
    const strict = await t.fetch("/strict");
    expect(strict.headers.getSetCookie()[0]).toContain("SameSite=Strict");

    t.app.get("/none", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: false },
      });
      return { session };
    });
    const none = await t.fetch("/none");
    expect(none.headers.getSetCookie()[0]).not.toContain("SameSite");
  });

  it("gets same session back", async () => {
    const result = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("set session data", async () => {
    const result = await t.fetch("/", {
      method: "POST",
      headers: { Cookie: cookie },
      body: JSON.stringify({ foo: "bar" }),
    });
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });

    const result2 = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result2.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });
  });

  it("gets same session back (concurrent)", async () => {
    app.get("/concurrent", async (event) => {
      const sessions = await Promise.all(
        [1, 2, 3].map(() =>
          useSession(event, sessionConfig).then((s) => ({
            id: s.id,
            data: s.data,
          })),
        ),
      );
      return {
        sessions,
      };
    });
    const result = await t.fetch("/concurrent", {
      headers: { Cookie: cookie },
    });
    expect(await result.json()).toMatchObject({
      sessions: [1, 2, 3].map(() => ({ id: "1", data: { foo: "bar" } })),
    });
  });

  it("clearSession sets maxAge=0 to delete cookie", async () => {
    t.app.get("/clear", async (event) => {
      await clearSession(event, sessionConfig);
      return { cleared: true };
    });
    const res = await t.fetch("/clear", {
      headers: { Cookie: cookie },
    });
    const cookies = res.headers.getSetCookie();
    expect(cookies.length).toBeGreaterThanOrEqual(1);
    expect(cookies[0]).toContain("Max-Age=0");
  });

  it("unseals and reseals legacy sessions sealed with iterations: 1", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    const result = await t.fetch("/", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    expect(await result.json()).toMatchObject({
      session: { id: "legacy", data: { foo: "legacy" } },
    });

    // Legacy cookie is transparently resealed with the current default
    const setCookies = result.headers.getSetCookie();
    expect(setCookies).toHaveLength(1);
    const resealed = decodeURIComponent(setCookies[0].match(/h3-test=([^;]+)/)![1]);
    expect(
      await unseal(resealed, sessionConfig.password, sealDefaults), // current iterations, no fallback
    ).toMatchObject({ id: "legacy", data: { foo: "legacy" } });
  });

  it("rejects legacy sessions with legacySealFallback: false", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    t.app.all("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        legacySealFallback: false,
      });
      return { session };
    });

    const result = await t.fetch("/strict", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    const body = await result.json();
    expect(body.session.id).not.toBe("legacy");
    expect(body.session.data).toEqual({});
  });

  it("accepts extraUnsealPasswords in SessionConfig", () => {
    const withExtra: SessionConfig = { password: NEW_PASSWORD, extraUnsealPasswords: [OLD_PASSWORD] };
    const withoutExtra: SessionConfig = { password: NEW_PASSWORD };
    expect(withExtra.extraUnsealPasswords).toEqual([OLD_PASSWORD]);
    expect(withoutExtra.extraUnsealPasswords).toBeUndefined();
  });

  it("opens a session sealed with an extra password as the old password would", async () => {
    sessionRoute("/extra-open", "get", extraConfig({ extraUnsealPasswords: [OLD_PASSWORD] }));
    sessionRoute("/old-only", "get", extraConfig({ password: OLD_PASSWORD }));
    const cookie = { headers: { Cookie: `h3-extra=${await sealWith(OLD_PASSWORD)}` } };

    const withExtra = await t.fetch("/extra-open", cookie);
    const oldOnly = await t.fetch("/old-only", cookie);
    const body = await withExtra.json();
    expect(body).toEqual({ id: "old-id", data: { foo: "bar" } });
    expect(body).toEqual(await oldOnly.json());
  });

  it("does not try extra passwords when the current password opens the session", async () => {
    sessionRoute("/plain", "get", extraConfig({ password: OLD_PASSWORD }));
    sessionRoute(
      "/with-extra",
      "get",
      extraConfig({ password: OLD_PASSWORD, extraUnsealPasswords: [OTHER_PASSWORD] }),
    );
    const cookie = { headers: { Cookie: `h3-extra=${await sealWith(OLD_PASSWORD)}` } };

    const plain = await countDerivations(() => t.fetch("/plain", cookie));
    const withExtra = await countDerivations(() => t.fetch("/with-extra", cookie));
    expect(plain.derivations).toBeGreaterThan(0);
    expect(withExtra.derivations).toBe(plain.derivations);
  });

  it("tries the next extra after a wrong one, costing one more failed attempt", async () => {
    sessionRoute("/tried-once", "get", extraConfig({ extraUnsealPasswords: [OLD_PASSWORD] }));
    sessionRoute(
      "/tried-twice",
      "get",
      extraConfig({ extraUnsealPasswords: [OTHER_PASSWORD, OLD_PASSWORD] }),
    );
    sessionRoute("/only-other", "get", extraConfig({ password: OTHER_PASSWORD }));
    const cookie = { headers: { Cookie: `h3-extra=${await sealWith(OLD_PASSWORD)}` } };

    const once = await countDerivations(() => t.fetch("/tried-once", cookie));
    const twice = await countDerivations(() => t.fetch("/tried-twice", cookie));
    const failed = await countDerivations(() => t.fetch("/only-other", cookie));
    expect(await twice.result.json()).toEqual({ id: "old-id", data: { foo: "bar" } });
    expect(failed.derivations).toBeGreaterThan(0);
    expect(twice.derivations - once.derivations).toBe(failed.derivations);
  });

  it("treats an extra equal to password as no extra", async () => {
    sessionRoute("/plain-new", "get", extraConfig());
    sessionRoute("/same-extra", "get", extraConfig({ extraUnsealPasswords: [NEW_PASSWORD] }));
    const cookie = { headers: { Cookie: `h3-extra=${await sealWith(NEW_PASSWORD)}` } };

    const plain = await countDerivations(() => t.fetch("/plain-new", cookie));
    const same = await countDerivations(() => t.fetch("/same-extra", cookie));
    expect(same.derivations).toBe(plain.derivations);
    expect(await same.result.json()).toEqual({ id: "old-id", data: { foo: "bar" } });
  });

  it("seals new sessions only with password, never with an extra", async () => {
    t.app.get("/create", async (event) => {
      const config = extraConfig({ extraUnsealPasswords: [OLD_PASSWORD] });
      await useSession(event, config);
      return { sealed: await sealSession(event, config) };
    });
    const res = await t.fetch("/create");
    const { sealed } = await res.json();
    const [cookie] = res.headers.getSetCookie();
    expect(await unseal(cookieValueOf(cookie), NEW_PASSWORD, sealDefaults)).toMatchObject({
      data: {},
    });
    await expect(unseal(cookieValueOf(cookie), OLD_PASSWORD, sealDefaults)).rejects.toThrow();
    expect(await unseal(sealed, NEW_PASSWORD, sealDefaults)).toMatchObject({ data: {} });
    await expect(unseal(sealed, OLD_PASSWORD, sealDefaults)).rejects.toThrow();
  });

  it("reseals a session opened with an extra password when read from a cookie", async () => {
    sessionRoute("/migrate", "get", extraConfig({ extraUnsealPasswords: [OLD_PASSWORD] }));
    const sealed = await sealWith(OLD_PASSWORD);

    const first = await t.fetch("/migrate", { headers: { Cookie: `h3-extra=${sealed}` } });
    expect(await first.json()).toEqual({ id: "old-id", data: { foo: "bar" } });
    const setCookies = first.headers.getSetCookie();
    expect(setCookies).toHaveLength(1);
    const resealed = cookieValueOf(setCookies[0]);
    await expect(unseal(resealed, OLD_PASSWORD, sealDefaults)).rejects.toThrow();
    expect(await unseal(resealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
      id: "old-id",
      data: { foo: "bar" },
    });

    const second = await t.fetch("/migrate", { headers: { Cookie: `h3-extra=${resealed}` } });
    expect(await second.json()).toEqual({ id: "old-id", data: { foo: "bar" } });
    expect(second.headers.getSetCookie()).toEqual([]);
  });

  it("does not reseal a session read from the session header", async () => {
    sessionRoute("/header", "get", extraConfig({ extraUnsealPasswords: [OLD_PASSWORD] }));
    const sealed = await sealWith(OLD_PASSWORD);

    const res = await t.fetch("/header", { headers: { "x-h3-extra-session": sealed } });
    expect(await res.json()).toEqual({ id: "old-id", data: { foo: "bar" } });
    expect(res.headers.getSetCookie()).toEqual([]);
  });

  it("keeps the session valid when the response can no longer carry the reseal", async () => {
    t.app.get("/sent", async (event) => {
      // Response headers already sent: Set-Cookie can no longer be appended
      const { headers } = event.res;
      const append = headers.append.bind(headers);
      headers.append = (name, value) => {
        if (name === "set-cookie") {
          throw new Error("Headers already sent");
        }
        append(name, value);
      };
      const session = await getSession(event, extraConfig({ extraUnsealPasswords: [OLD_PASSWORD] }));
      return { id: session.id, data: session.data };
    });
    const res = await t.fetch("/sent", {
      headers: { Cookie: `h3-extra=${await sealWith(OLD_PASSWORD)}` },
    });
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual({ id: "old-id", data: { foo: "bar" } });
    // The reseal was attempted and deferred, so no cookie was written
    expect(res.headers.getSetCookie()).toEqual([]);
  });

  it("keeps the responses the same when extraUnsealPasswords is absent, undefined or empty", async () => {
    const variants: Record<string, Partial<SessionConfig>> = {
      absent: {},
      undefined: { extraUnsealPasswords: undefined },
      empty: { extraUnsealPasswords: [] },
    };
    const cookies = {
      newCookie: await sealWith(NEW_PASSWORD),
      oldCookie: await sealWith(OLD_PASSWORD),
      outraCookie: await sealWith(OTHER_PASSWORD),
    };
    for (const [variant, overrides] of Object.entries(variants)) {
      const config = extraConfig({ name: "h3-ref", ...overrides });
      sessionRoute(`/${variant}/get`, "get", config);
      sessionRoute(`/${variant}/use`, "use", config);
    }
    for (const [variant] of Object.entries(variants)) {
      for (const [cookieName, sealed] of Object.entries(cookies)) {
        for (const mode of ["get", "use"]) {
          const res = await t.fetch(`/${variant}/${mode}`, {
            headers: { Cookie: `h3-ref=${sealed}` },
          });
          const actual = { status: res.status, cookies: cookieShape(res), body: await res.json() };
          expect(actual).toEqual(REFERENCE[`${variant}|${cookieName}|${mode}`]);
        }
      }
    }
  });

  it("unsealSession keeps the error when no password opens the session", async () => {
    const sealed = await sealWith(OLD_PASSWORD);
    for (const [variant, overrides] of [
      ["absent", {}],
      ["undefined", { extraUnsealPasswords: undefined }],
      ["empty", { extraUnsealPasswords: [] }],
    ] as const) {
      const error = await unsealSession({} as H3Event, extraConfig(overrides), sealed).then(
        () => undefined,
        (caught: Error) => ({ ctor: caught.constructor.name, message: caught.message }),
      );
      expect(error).toEqual(REFERENCE[`direct|${variant}|old`]);
